// ═══════════════════════════════════════════
// CURSOR (desativado em dispositivos de toque)
// ═══════════════════════════════════════════
const isTouchDevice = window.matchMedia('(hover: none), (pointer: coarse)').matches;
const cursor = document.getElementById('cursor');
const cursorRing = document.getElementById('cursorRing');

if(!isTouchDevice){
  let mouseX=0,mouseY=0,ringX=0,ringY=0;
  document.addEventListener('mousemove',e=>{
    mouseX=e.clientX; mouseY=e.clientY;
    cursor.style.left=mouseX+'px'; cursor.style.top=mouseY+'px';
  });
  function animateRing(){
    ringX+=(mouseX-ringX)*.12;
    ringY+=(mouseY-ringY)*.12;
    cursorRing.style.left=ringX+'px'; cursorRing.style.top=ringY+'px';
    requestAnimationFrame(animateRing);
  }
  animateRing();
  document.querySelectorAll('a,button,[onclick]').forEach(el=>{
    el.addEventListener('mouseenter',()=>{cursor.classList.add('hovering');cursorRing.classList.add('hovering')});
    el.addEventListener('mouseleave',()=>{cursor.classList.remove('hovering');cursorRing.classList.remove('hovering')});
  });
}

// ═══════════════════════════════════════════
// LOADER
// ═══════════════════════════════════════════
window.addEventListener('load',()=>{
  const loader=document.getElementById('pageLoader');
  if(sessionStorage.getItem('lt_visited')){
    loader.style.transition='none';
    loader.classList.add('hidden');
  } else {
    setTimeout(()=>loader.classList.add('hidden'),1400);
    sessionStorage.setItem('lt_visited','1');
  }
  renderProducts();
  updateCartBadge();
  renderReviews();
  initStarPicker();
  initScrollReveal();
  initFirebaseSync();
  if(STATE.user) document.getElementById('authLabel').textContent = STATE.user.name.split(' ')[0];
});

// ═══════════════════════════════════════════
// NAV SCROLL
// ═══════════════════════════════════════════
window.addEventListener('scroll',()=>{
  document.getElementById('mainNav').classList.toggle('scrolled',window.scrollY>60);
});
function scrollToTop(){window.scrollTo({top:0,behavior:'smooth'})}
function goTo(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}

// ═══════════════════════════════════════════
// MOBILE MENU
// ═══════════════════════════════════════════
function toggleMobile(){
  const m=document.getElementById('mobileMenu');
  m.classList.toggle('active');
  document.body.style.overflow=m.classList.contains('active')?'hidden':'';
}

// ═══════════════════════════════════════════
// SCROLL REVEAL
// ═══════════════════════════════════════════
function initScrollReveal(){
  const obs=new IntersectionObserver(entries=>{
    entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')});
  },{threshold:.1,rootMargin:'0px 0px -60px 0px'});
  document.querySelectorAll('.reveal').forEach(el=>obs.observe(el));
}

// ═══════════════════════════════════════════
// PRODUCTS RENDER
// ═══════════════════════════════════════════
function renderProducts(cat='all'){
  const grid=document.getElementById('productsGrid');
  const list=cat==='all'?STATE.products:STATE.products.filter(p=>p.category===cat);
  grid.innerHTML=list.map(p=>{
    const inStock=Object.values(p.sizes).some(q=>q>0);
    const priceHtml=p.oldPrice
      ?`<span class="price-new">R$ ${p.price.toFixed(2).replace('.',',')}</span><span class="price-old">R$ ${p.oldPrice.toFixed(2).replace('.',',')}</span>`
      :`R$ ${p.price.toFixed(2).replace('.',',')}`;
    const sizesHtml=Object.entries(p.sizes).map(([s,q])=>
      `<div class="size-dot ${q>0?'available':'unavailable'}">${s}</div>`
    ).join('');
    return `<div class="product-card" onclick="openProductDetail(${p.id})">
      <div class="product-img">
        ${p.image ? `<img src="${p.image}" alt="${sanitize(p.name)}" style="width:100%;height:100%;object-fit:cover;transition:transform .6s ease">` : `<div class="product-img-placeholder">
          <svg width="40" height="40" fill="none" stroke="currentColor" stroke-width="1" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
          <span style="font-family:var(--font-condensed);font-size:9px;letter-spacing:.1em;text-transform:uppercase;opacity:.5">Foto em breve</span>
        </div>`}
        ${p.badge?`<div class="product-badge${!inStock?' sold-out':''}">${inStock?p.badge:'Esgotado'}</div>`:''}
        ${!inStock&&!p.badge?`<div class="product-badge sold-out">Esgotado</div>`:''}
        <div class="product-actions">
          <button class="btn-add-cart" onclick="quickAddToCart(event,${p.id})">${inStock?'Adicionar':'Esgotado'}</button>
          <button class="btn-wishlist" onclick="toggleWishlist(event,${p.id})">♡</button>
        </div>
      </div>
      <div class="product-info">
        <div class="product-name">${sanitize(p.name)}</div>
        <div class="product-price">${priceHtml}</div>
        <div class="product-sizes">${sizesHtml}</div>
      </div>
    </div>`;
  }).join('');
}

function filterCategory(cat,btn){
  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderProducts(cat);
  scrollTo('products');
}

// ═══════════════════════════════════════════
// PRODUCT DETAIL
// ═══════════════════════════════════════════
function openProductDetail(id){
  const p=STATE.products.find(x=>x.id===id);
  if(!p) return;
  STATE.currentProduct=p;
  STATE.selectedSize=null;
  document.getElementById('detailCategory').textContent=p.category.charAt(0).toUpperCase()+p.category.slice(1);
  document.getElementById('detailName').textContent=p.name;
  document.getElementById('detailPrice').innerHTML=p.oldPrice
    ?`<span style="color:var(--accent)">R$ ${p.price.toFixed(2).replace('.',',')}</span> <span style="text-decoration:line-through;color:var(--gray-500);font-size:14px">R$ ${p.oldPrice.toFixed(2).replace('.',',')}</span>`
    :`R$ ${p.price.toFixed(2).replace('.',',')}`;
  document.getElementById('detailDesc').textContent=p.desc;
  // Sizes
  const sg=document.getElementById('detailSizes');
  sg.innerHTML=Object.entries(p.sizes).map(([s,q])=>
    `<button class="size-btn${q===0?' out':''}" onclick="selectSize('${s}',this)">${s}</button>`
  ).join('');
  // Gallery main
  const gm=document.getElementById('galleryMain');
  if(p.image){
    gm.innerHTML=`<img src="${p.image}" alt="${p.name}" style="width:100%;height:100%;object-fit:cover">`;
  } else {
    gm.innerHTML=`<div class="gallery-placeholder" style="height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:var(--gray-400)"><svg width="64" height="64" fill="none" stroke="currentColor" stroke-width="1" viewBox="0 0 24 24"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg><span style="font-family:var(--font-condensed);font-size:11px;letter-spacing:.1em;text-transform:uppercase">Foto em breve</span></div>`;
  }
  // Thumbs
  const thumbs=document.getElementById('galleryThumbs');
  thumbs.innerHTML=[1,2,3].map((i,idx)=>
    p.image ? `<div class="gallery-thumb${idx===0?' active':''}" onclick="selectThumb(this,this.querySelector('img').src)" style="overflow:hidden">
      <img src="${p.image}" alt="" style="width:100%;height:100%;object-fit:cover">
    </div>` :
    `<div class="gallery-thumb${idx===0?' active':''}" onclick="selectThumb(this,'')">
      <div class="gallery-placeholder" style="font-size:9px;display:flex;align-items:center;justify-content:center;height:100%;color:var(--gray-500)">Foto ${i}</div>
    </div>`
  ).join('');
  const btn=document.getElementById('btnAddToCart');
  btn.textContent='Selecione um tamanho';
  btn.disabled=true;
  document.getElementById('productDetailOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeProductDetail(){
  document.getElementById('productDetailOverlay').classList.remove('active');
  document.body.style.overflow='';
}
function selectSize(s,el){
  const p=STATE.currentProduct;
  if(p.sizes[s]===0) return;
  document.querySelectorAll('.size-btn').forEach(b=>b.classList.remove('selected'));
  el.classList.add('selected');
  STATE.selectedSize=s;
  const btn=document.getElementById('btnAddToCart');
  btn.textContent='Adicionar ao carrinho';
  btn.disabled=false;
}
function selectThumb(el,src){
  document.querySelectorAll('.gallery-thumb').forEach(t=>t.classList.remove('active'));
  el.classList.add('active');
  if(src){document.getElementById('galleryMain').innerHTML=`<img src="${src}" alt="" style="width:100%;height:100%;object-fit:cover">`;}
}
function addToCartFromDetail(){
  if(!STATE.selectedSize) return;
  addToCart(STATE.currentProduct.id, STATE.selectedSize);
  closeProductDetail();
}
function checkStockWhatsapp(){
  const p = STATE.currentProduct;
  if(!p) return;
  let msg = `Olá! Vim pelo site da LT Company e queria confirmar se ainda tem em estoque:\n\n`;
  msg += `▪️ *${p.name}*\n`;
  if(STATE.selectedSize){
    msg += `Tamanho: ${STATE.selectedSize}\n`;
  } else {
    msg += `(ainda não escolhi o tamanho)\n`;
  }
  msg += `\nPode confirmar pra mim? Obrigado(a)!`;
  const encodedMsg = encodeURIComponent(msg);
  window.open(`https://wa.me/${STORE_WHATSAPP}?text=${encodedMsg}`, '_blank');
}

// ═══════════════════════════════════════════
// CART
// ═══════════════════════════════════════════
function addToCart(id, size=null){
  const p=STATE.products.find(x=>x.id===id);
  if(!p) return;
  if(!size){
    const avail=Object.entries(p.sizes).find(([s,q])=>q>0);
    if(!avail){showToast('Produto esgotado','error');return;}
    size=avail[0];
  }
  const key=`${id}-${size}`;
  const existing=STATE.cart.find(i=>i.key===key);
  if(existing){
    existing.qty++;
  } else {
    STATE.cart.push({key,id,name:p.name,price:p.price,size,qty:1});
  }
  saveCart();
  showToast(`${p.name} adicionado ao carrinho`,'success');
}
function quickAddToCart(e,id){
  e.stopPropagation();
  openProductDetail(id);
}
function toggleWishlist(e,id){
  e.stopPropagation();
  const p=STATE.products.find(x=>x.id===id);
  const idx=STATE.wishlist.indexOf(id);
  if(idx>-1){STATE.wishlist.splice(idx,1);showToast('Removido da lista de desejos');}
  else{STATE.wishlist.push(id);showToast(`${p.name} adicionado à lista de desejos`,'success');}
  localStorage.setItem('lt_wishlist',JSON.stringify(STATE.wishlist));
}
function addToWishlist(){
  if(STATE.currentProduct) toggleWishlist({stopPropagation:()=>{}},STATE.currentProduct.id);
}
function saveCart(){
  localStorage.setItem('lt_cart',JSON.stringify(STATE.cart));
  updateCartBadge();
  if(document.getElementById('cartOverlay').classList.contains('active')) renderCart();
}
function updateCartBadge(){
  const total=STATE.cart.reduce((s,i)=>s+i.qty,0);
  document.getElementById('cartBadge').textContent=total;
  document.getElementById('cartCount').textContent=total;
}
function openCart(){
  renderCart();
  document.getElementById('cartOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeCart(){
  document.getElementById('cartOverlay').classList.remove('active');
  document.body.style.overflow='';
}
function renderCart(){
  const empty=document.getElementById('cartEmpty');
  const items=document.getElementById('cartItems');
  const footer=document.getElementById('cartFooter');
  if(STATE.cart.length===0){
    empty.style.display='block';items.innerHTML='';footer.style.display='none';return;
  }
  empty.style.display='none';footer.style.display='block';
  items.innerHTML=STATE.cart.map(item=>`
    <div class="cart-item">
      <div class="cart-item-img">Foto<br>em breve</div>
      <div class="cart-item-details">
        <div class="cart-item-name">${sanitize(item.name)}</div>
        <div class="cart-item-meta">Tamanho: ${item.size}</div>
        <div class="cart-item-controls">
          <div class="qty-ctrl">
            <button onclick="updateQty('${item.key}',-1)">−</button>
            <span>${item.qty}</span>
            <button onclick="updateQty('${item.key}',1)">+</button>
          </div>
          <div class="cart-item-price">R$ ${(item.price*item.qty).toFixed(2).replace('.',',')}</div>
        </div>
        <button class="cart-remove" onclick="removeFromCart('${item.key}')">Remover</button>
      </div>
    </div>`).join('');
  updateCartTotals();
}
function updateQty(key,delta){
  const item=STATE.cart.find(i=>i.key===key);
  if(!item) return;
  item.qty=Math.max(1,item.qty+delta);
  saveCart();renderCart();
}
function removeFromCart(key){
  STATE.cart=STATE.cart.filter(i=>i.key!==key);
  saveCart();renderCart();
}
function updateCartTotals(){
  const sub=STATE.cart.reduce((s,i)=>s+i.price*i.qty,0);
  const disc=sub*STATE.discount;
  const total=sub-disc;
  document.getElementById('cartSubtotal').textContent=`R$ ${sub.toFixed(2).replace('.',',')}`;
  document.getElementById('cartDiscount').textContent=disc>0?`−R$ ${disc.toFixed(2).replace('.',',')}`:'—';
  document.getElementById('cartTotal').textContent=`R$ ${total.toFixed(2).replace('.',',')}`;
}
const DEFAULT_COUPONS=[
  {code:'LT10',discount:.10,active:true},
  {code:'LT20',discount:.20,active:true},
  {code:'LTFIRST',discount:.15,active:true},
  {code:'LTCOMPANY',discount:.25,active:true},
  {code:'PRIMEIRACOMPRA',discount:.10,active:true}
];
STATE.coupons = JSON.parse(localStorage.getItem('lt_coupons') || 'null') || DEFAULT_COUPONS;
function applyCoupon(){
  const code=document.getElementById('couponInput').value.trim().toUpperCase();
  const c = STATE.coupons.find(x=>x.code===code && x.active);
  if(c){
    STATE.discount=c.discount;
    showToast(`Cupom aplicado: ${(c.discount*100).toFixed(0)}% de desconto`,'success');
  } else {
    showToast('Cupom inválido ou expirado','error');
  }
  updateCartTotals();
}
// Número da loja para receber pedidos via WhatsApp
const STORE_WHATSAPP = '556292767253';

function checkout(){
  if(STATE.cart.length===0){
    showToast('Seu carrinho está vazio','error');
    return;
  }
  if(!STATE.user){
    closeCart();
    openAuth();
    showToast('Faça login para finalizar a compra');
    return;
  }

  const sub = STATE.cart.reduce((s,i)=>s+i.price*i.qty,0);
  const disc = sub*STATE.discount;
  const total = sub-disc;

  // Monta a mensagem do pedido
  let msg = `🛍️ *NOVO PEDIDO - LT COMPANY*\n\n`;
  msg += `👤 *Cliente:* ${STATE.user.name}\n`;
  msg += `📧 *E-mail:* ${STATE.user.email}\n\n`;
  msg += `📦 *PRODUTOS:*\n`;
  STATE.cart.forEach(item=>{
    msg += `▪️ ${item.name}\n`;
    msg += `   Tamanho: ${item.size} | Qtd: ${item.qty} | R$ ${(item.price*item.qty).toFixed(2).replace('.',',')}\n`;
  });
  msg += `\n💰 *Subtotal:* R$ ${sub.toFixed(2).replace('.',',')}\n`;
  if(disc>0){
    msg += `🏷️ *Desconto:* −R$ ${disc.toFixed(2).replace('.',',')}\n`;
  }
  msg += `✅ *TOTAL A PAGAR: R$ ${total.toFixed(2).replace('.',',')}*\n\n`;
  msg += `Por favor, confirme a disponibilidade em estoque desses itens e a forma de pagamento (PIX, cartão de crédito ou débito). Aguardo retorno! 🙏`;

  const encodedMsg = encodeURIComponent(msg);
  const whatsappUrl = `https://wa.me/${STORE_WHATSAPP}?text=${encodedMsg}`;

  showToast('Redirecionando para o WhatsApp...','success');
  setTimeout(()=>{
    window.open(whatsappUrl, '_blank');
  }, 600);
}

// ═══════════════════════════════════════════
// AUTH (client-side simulation — use backend hash in production)
// ═══════════════════════════════════════════
function openAuth(){document.getElementById('authOverlay').classList.add('active');document.body.style.overflow='hidden';}
function loginWithGoogle(){
  if(!window.fb){ showToast('Carregando, tente novamente em instantes.','error'); return; }
  window.fb.signInGoogle().then(result=>{
    const u = result.user;
    const firstName = (u.displayName||u.email.split('@')[0]).split(' ')[0];
    const user = {id:u.uid, name:u.displayName||firstName, email:u.email, photo:u.photoURL};
    STATE.user = user;
    localStorage.setItem('lt_user', JSON.stringify(user));
    const authLabel = document.getElementById('authLabel');
    if(authLabel) authLabel.textContent = firstName;
    closeAuth();
    showToast(`Bem-vindo(a), ${firstName}!`,'success');
    window.fb.upsertCustomer(u.uid, {name:u.displayName||firstName, email:u.email, photo:u.photoURL||null}).catch(err=>console.error('upsertCustomer error:',err));
  }).catch(err=>{
    console.error(err);
    showToast('Não foi possível entrar com Google. Tente novamente.','error');
  });
}

function closeAuth(){document.getElementById('authOverlay').classList.remove('active');document.body.style.overflow='';}

function initFirebaseSync(){
  function ready(){
    window.fb.seedProducts(DEMO_PRODUCTS).catch(err=>console.error('Seed error:',err));
    window.fb.seedCoupons(DEFAULT_COUPONS).catch(err=>console.error('Seed coupons error:',err));
    window.fb.listenProducts(products=>{
      if(products.length===0) return; // ainda não semeou / offline
      STATE.products = products;
      localStorage.setItem('lt_products', JSON.stringify(products));
      renderProducts(STATE.currentFilter||'all');
      if(document.getElementById('adminOverlay').style.display==='flex'){
        renderAdminSection('products');
      }
    });
    window.fb.listenCoupons(coupons=>{
      if(coupons.length===0) return;
      STATE.coupons = coupons;
      localStorage.setItem('lt_coupons', JSON.stringify(coupons));
      if(document.getElementById('adminOverlay').style.display==='flex'){
        renderAdminSection('coupons');
      }
    });
    window.fb.onAuthStateChanged(user=>{
      STATE.isAdmin = !!(user && window.fb.isAdminEmail(user.email));
      if(STATE.isAdmin && !STATE._customersListening){
        STATE._customersListening = true;
        window.fb.listenCustomers(customers=>{
          STATE.customers = customers;
          if(document.getElementById('adminOverlay').style.display==='flex'){
            renderAdminSection('users');
          }
        });
      }
    });
  }
  if(window.fb) ready();
  else window.addEventListener('fbReady', ready, {once:true});
}

