function openInfo(key){
  const info = INFO_CONTENT[key];
  if(!info) return;
  document.getElementById('infoTitle').textContent = info.title;
  document.getElementById('infoBody').innerHTML = info.body;
  document.getElementById('infoOverlay').classList.add('active');
  document.body.style.overflow='hidden';
}
function closeInfo(){document.getElementById('infoOverlay').classList.remove('active');document.body.style.overflow='';}
function switchTab(tab,btn){
  ['login','register','forgot'].forEach(t=>{
    document.getElementById('tab'+t.charAt(0).toUpperCase()+t.slice(1)).style.display=t===tab?'block':'none';
  });
  document.querySelectorAll('.auth-tab').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
}
function clearErrors(){document.querySelectorAll('.form-error').forEach(e=>e.classList.remove('visible'));}

// Simple client-side validation (production: server-side with bcrypt)
function handleLogin(){
  const email=document.getElementById('loginEmail').value.trim();
  const pass=document.getElementById('loginPassword').value;
  if(!email||!email.includes('@')){document.getElementById('loginEmailError').classList.add('visible');return;}
  if(!pass||pass.length<6){document.getElementById('loginPassError').classList.add('visible');return;}
  const user=STATE.users.find(u=>u.email===email&&u.password===btoa(pass));
  if(!user){document.getElementById('loginPassError').textContent='E-mail ou senha incorretos';document.getElementById('loginPassError').classList.add('visible');return;}
  loginUser(user);
}
function handleRegister(){
  const n=document.getElementById('regName').value.trim();
  const e=document.getElementById('regEmail').value.trim();
  const p=document.getElementById('regPassword').value;
  const c=document.getElementById('regConfirm').value;
  if(!n||!e||!p){showToast('Preencha todos os campos','error');return;}
  if(p!==c){document.getElementById('regConfirmError').classList.add('visible');return;}
  if(p.length<8){showToast('Senha deve ter ao menos 8 caracteres','error');return;}
  if(STATE.users.find(u=>u.email===e)){showToast('E-mail já cadastrado','error');return;}
  const user={id:Date.now(),name:sanitize(n),email:sanitize(e),password:btoa(p),createdAt:new Date().toISOString()};
  STATE.users.push(user);
  localStorage.setItem('lt_users',JSON.stringify(STATE.users));
  loginUser(user);
  showToast(`Bem-vindo(a), ${user.name.split(' ')[0]}!`,'success');
}
function handleForgot(){
  const e=document.getElementById('forgotEmail').value.trim();
  if(!e||!e.includes('@')){showToast('Informe um e-mail válido','error');return;}
  showToast('Instruções enviadas para '+e,'success');
  setTimeout(()=>switchTab('login',document.querySelectorAll('.auth-tab')[0]),2000);
}
function loginUser(user){
  STATE.user=user;
  localStorage.setItem('lt_user',JSON.stringify(user));
  document.getElementById('authLabel').textContent=user.name.split(' ')[0];
  closeAuth();
}
function checkPasswordStrength(input){
  const v=input.value;const bar=document.getElementById('strengthBar');
  let s=0;
  if(v.length>=8)s++;if(/[A-Z]/.test(v))s++;if(/[0-9]/.test(v))s++;if(/[^a-zA-Z0-9]/.test(v))s++;
  bar.style.width=(s/4*100)+'%';
  bar.style.background=['var(--danger)','#e08830','#e0c030','var(--success)'][s-1]||'var(--danger)';
}
function formatCpf(input){
  let v=input.value.replace(/\D/g,'');
  if(v.length>3)v=v.substring(0,3)+'.'+v.substring(3);
  if(v.length>7)v=v.substring(0,7)+'.'+v.substring(7);
  if(v.length>11)v=v.substring(0,11)+'-'+v.substring(11,13);
  input.value=v;
}

