// ADMIN PANEL
// ═══════════════════════════════════════════
function showAdmin(){
  if(!window.fb){ showToast('Carregando sistema, tente novamente em instantes.','error'); return; }
  const current = window.fb.auth.currentUser;
  if(current && window.fb.isAdminEmail(current.email)){
    openAdminPanel();
    return;
  }
  const email = prompt('E-mail do admin:');
  if(!email) return;
  const pass = prompt('Senha:');
  if(!pass) return;
  window.fb.signInAdmin(email.trim(), pass).then(cred=>{
    if(!window.fb.isAdminEmail(cred.user.email)){
      window.fb.signOutAdmin();
      showToast('Acesso negado. Essa conta não tem permissão de admin.','error');
      return;
    }
    openAdminPanel();
  }).catch(()=>{
    showToast('E-mail ou senha incorretos.','error');
  });
}
function openAdminPanel(){
  document.getElementById('adminOverlay').style.display='flex';
  document.body.style.overflow='hidden';
  renderAdminSection('dashboard');
}
function hideAdmin(){
  document.getElementById('adminOverlay').style.display='none';
  document.body.style.overflow='';
}
function adminSection(sec,el){
  document.querySelectorAll('.adm-item').forEach(i=>i.classList.remove('active'));
  el.classList.add('active');
  renderAdminSection(sec);
}
function renderAdminSection(sec){
  const titles={dashboard:'Dashboard',products:'Produtos',orders:'Pedidos',users:'Usuários',coupons:'Cupons',reports:'Relatórios'};
  document.getElementById('adminTitle').textContent=titles[sec]||sec;
  const c=document.getElementById('adminContent');
  if(sec==='dashboard') c.innerHTML=renderDashboard();
  else if(sec==='products') c.innerHTML=renderAdminProducts();
  else if(sec==='orders') c.innerHTML=renderAdminOrders();
  else if(sec==='users') c.innerHTML=renderAdminUsers();
  else if(sec==='coupons') c.innerHTML=renderAdminCoupons();
  else if(sec==='reports') c.innerHTML=renderAdminReports();
}
